mapper.select:
select id, order_id, type, payload, reason, status, requester_id, requester_name, create_time,
       handler_id, handler_name, handle_note, handle_time
from jiedan_approval where id = #{id}

select 
from jiedan_approval a
left join jiedan_order o on o.id = a.order_id

    and a.status = #{status}
    and a.requester_id = #{requesterId}

order by case when a.status = 'pending' then 0 else 1 end, a.id desc
limit #{limit}
